import React from "react";
import "./../../css/Login.css";
import withRouter from "../withRouter";
import { Link } from "react-router-dom";

class Login extends React.Component {
    constructor(props) {
        super(props);

        this.state = {
            phone: "",
            password: "",
            remember: false,
            showPassword: false,
            loading: false,
            error: "",
            success: "",
            darkMode: window.matchMedia("(prefers-color-scheme: dark)").matches
        };

        this.messageTimer = null;
    }

    componentDidMount() {
        this.themeQuery = window.matchMedia("(prefers-color-scheme: dark)");

        this.themeQuery.addEventListener("change", this.handleThemeChange);
    }

    componentWillUnmount() {
        clearTimeout(this.messageTimer);

        if (this.themeQuery) {
            this.themeQuery.removeEventListener("change", this.handleThemeChange);
        }
    }

    handleThemeChange = (e) => {
        this.setState({ darkMode: e.matches });
    };

    showMessage = (type, message) => {
        clearTimeout(this.messageTimer);

        this.setState({
            error: type === "error" ? message : "",
            success: type === "success" ? message : ""
        });

        this.messageTimer = setTimeout(() => {
            this.setState({
                error: "",
                success: ""
            });
        }, 3000);
    };

    closeMessage = () => {
        clearTimeout(this.messageTimer);

        this.setState({
            error: "",
            success: ""
        });
    };

    handleChange = (e) => {
        const { name, value, type, checked } = e.target;

        this.setState({
            [name]: type === "checkbox" ? checked : value,
            error: "",
            success: ""
        });

        clearTimeout(this.messageTimer);
    };

    handleSubmit = (e) => {
        e.preventDefault();

        const { phone, password } = this.state;

        if (!phone.trim() || !password) {
            this.showMessage(
                "error",
                "لطفاً شماره موبایل و رمز عبور خود را وارد کنید."
            );
            return;
        }

        if (!/^09\d{9}$/.test(phone.trim())) {
            this.showMessage(
                "error",
                "شماره موبایل واردشده معتبر نیست."
            );
            return;
        }

        this.setState({
            loading: true,
            error: "",
            success: ""
        });

        clearTimeout(this.messageTimer);

        fetch("http://laclinique.rezaavareh.ir/api/login", {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                Accept: "application/json"
            },
            body: JSON.stringify({
                phone: phone.trim(),
                password: password
            })
        })
            .then((response) => {
                return response.json().then((result) => {
                    if (!response.ok || !result.success) {
                        if (result.errors) {
                            const errors = Object.values(result.errors).flat();

                            throw new Error(
                                errors.join(" ") ||
                                result.message ||
                                "اطلاعات واردشده صحیح نیست."
                            );
                        }

                        throw new Error(
                            result.message || "ورود به حساب کاربری ناموفق بود."
                        );
                    }

                    return result;
                });
            })
            .then((result) => {
                if (!result.token) {
                    throw new Error("توکن ورود از سرور دریافت نشد.");
                }

                localStorage.setItem("token", result.token);

                this.showMessage(
                    "success",
                    result.message || "ورود با موفقیت انجام شد."
                );

                setTimeout(() => {
                    this.props.navigate("/");
                }, 700);
            })
            .catch((error) => {
                console.error("Login Error:", error);

                this.showMessage(
                    "error",
                    error instanceof TypeError
                        ? "ارتباط با سرور برقرار نشد. اتصال خود را بررسی کنید."
                        : error.message || "خطایی هنگام ورود رخ داد."
                );
            })
            .finally(() => {
                this.setState({ loading: false });
            });
    };

    render() {
        const { darkMode } = this.state;

        return (
            <div
                className={`login-page ${darkMode ? "dark-theme" : ""}`}
                dir="rtl"
            >
                {(this.state.error || this.state.success) && (
                    <div
                        className={`login-toast ${
                            this.state.error
                                ? "login-toast-error"
                                : "login-toast-success"
                        }`}
                        role={this.state.error ? "alert" : "status"}
                    >
                        <span className="login-toast-icon">
                            {this.state.error ? "!" : "✓"}
                        </span>

                        <span className="login-toast-text">
                            {this.state.error || this.state.success}
                        </span>

                        <button
                            type="button"
                            className="login-toast-close"
                            onClick={this.closeMessage}
                        >
                            ×
                        </button>
                    </div>
                )}

                <div className="login-shell">

                    <div className="login-topbar">
                        <button
                            className="login-icon-btn login-invisible"
                            type="button"
                        />

                        <button
                            className="login-icon-btn"
                            type="button"
                            aria-label="بازگشت"
                            onClick={() => this.props.navigate("/")}
                        >
                            <svg
                                width="17"
                                height="17"
                                viewBox="0 0 24 24"
                                fill="none"
                                stroke="currentColor"
                                strokeWidth="2"
                                strokeLinecap="round"
                            >
                                <path d="M18 6 6 18M6 6l12 12" />
                            </svg>
                        </button>
                    </div>

                    <div className="login-content">

                        <div className="login-brand">
                            <div className="login-brand-logo">
                                <svg
                                    width="30"
                                    height="30"
                                    viewBox="0 0 24 24"
                                    fill="none"
                                    stroke="currentColor"
                                    strokeWidth="2"
                                    strokeLinecap="round"
                                    strokeLinejoin="round"
                                >
                                    <path d="M12 3v18M3 12h18M5.6 5.6l12.8 12.8M18.4 5.6 5.6 18.4" />
                                </svg>
                            </div>

                            <div className="login-brand-name">
                                اوراکلینیک
                            </div>

                            <div className="login-brand-sub">
                                کلینیک زیبایی
                            </div>
                        </div>

                        <div className="login-main">

                            <div className="login-heading">
                                به اوراکلینیک خوش آمدید
                            </div>

                            <p className="login-description">
                                برای ورود به حساب کاربری، اطلاعات خود را وارد کنید.
                            </p>

                            <form onSubmit={this.handleSubmit} noValidate>

                                <div className="login-field">

                                    <label htmlFor="phone">
                                        شماره موبایل
                                    </label>

                                    <div className="login-input-wrap phone-input-wrap">

                                        <div className="login-phone-code">
                                            <span>🇮🇷</span>
                                            <span>+۹۸</span>
                                        </div>

                                        <input
                                            id="phone"
                                            type="tel"
                                            name="phone"
                                            value={this.state.phone}
                                            onChange={this.handleChange}
                                            placeholder="09121234567"
                                            maxLength={11}
                                            inputMode="numeric"
                                            autoComplete="tel"
                                            dir="ltr"
                                        />

                                    </div>

                                </div>

                                <div className="login-field">

                                    <label htmlFor="password">
                                        رمز عبور
                                    </label>

                                    <div className="login-input-wrap">

                                        <input
                                            id="password"
                                            type={
                                                this.state.showPassword
                                                    ? "text"
                                                    : "password"
                                            }
                                            name="password"
                                            value={this.state.password}
                                            onChange={this.handleChange}
                                            placeholder="رمز عبور خود را وارد کنید"
                                            autoComplete="current-password"
                                        />

                                        <button
                                            className="password-toggle"
                                            type="button"
                                            onClick={() =>
                                                this.setState({
                                                    showPassword: !this.state.showPassword
                                                })
                                            }
                                            aria-label="نمایش یا مخفی کردن رمز عبور"
                                        >
                                            {this.state.showPassword ? (
                                                <svg
                                                    width="21"
                                                    height="21"
                                                    viewBox="0 0 24 24"
                                                    fill="none"
                                                    stroke="currentColor"
                                                    strokeWidth="1.8"
                                                    strokeLinecap="round"
                                                    strokeLinejoin="round"
                                                >
                                                    <path d="M3 3l18 18M10.6 10.6a2 2 0 0 0 2.8 2.8M9.9 5.2A10.8 10.8 0 0 1 12 5c5 0 9 7 9 7a16 16 0 0 1-4 4.5M6.2 6.2C3.5 8 2 12 2 12s4 7 10 7a9.8 9.8 0 0 0 3-.5" />
                                                </svg>
                                            ) : (
                                                <svg
                                                    width="21"
                                                    height="21"
                                                    viewBox="0 0 24 24"
                                                    fill="none"
                                                    stroke="currentColor"
                                                    strokeWidth="1.8"
                                                    strokeLinecap="round"
                                                    strokeLinejoin="round"
                                                >
                                                    <path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7-10-7-10-7Z" />
                                                    <circle cx="12" cy="12" r="3" />
                                                </svg>
                                            )}
                                        </button>

                                    </div>

                                </div>

                                <div className="login-options">

                                    <label className="remember-option">
                                        <input
                                            type="checkbox"
                                            name="remember"
                                            checked={this.state.remember}
                                            onChange={this.handleChange}
                                        />

                                        <span>مرا به خاطر بسپار</span>
                                    </label>

                                </div>

                                <button
                                    className="login-submit"
                                    type="submit"
                                    disabled={this.state.loading}
                                >
                                    {this.state.loading ? (
                                        <span className="login-loading">
                                            <span className="login-spinner" />
                                            در حال ورود...
                                        </span>
                                    ) : (
                                        <>
                                            <span>ورود به حساب کاربری</span>

                                            <svg
                                                width="18"
                                                height="18"
                                                viewBox="0 0 24 24"
                                                fill="none"
                                                stroke="currentColor"
                                                strokeWidth="2.2"
                                                strokeLinecap="round"
                                                strokeLinejoin="round"
                                            >
                                                <path d="m15 6-6 6 6 6" />
                                            </svg>
                                        </>
                                    )}
                                </button>

                                <div className="login-register">
                                    حساب کاربری ندارید؟

                                    <Link
                                        to="/register"
                                        className="register-login-btn"
                                    >
                                        ثبت‌نام کنید
                                    </Link>
                                </div>

                            </form>

                        </div>

                        <div className="login-footer">
                            با ورود به اوراکلینیک، شرایط استفاده و حریم خصوصی را می‌پذیرید.
                        </div>

                    </div>

                </div>
            </div>
        );
    }
}

export default withRouter(Login);
